{
  "name": "@frontendxlab/opencode-visual-inspector",
  "version": "1.5.1",
  "description": "Select web UI elements and send precise visual change requests to OpenCode",
  "type": "module",
  "main": "./src/index.ts",
  "bin": {
    "opencode-visual-inspector": "./bin/opencode-visual-inspector.mjs"
  },
  "exports": {
    ".": "./src/index.ts",
    "./v1": "./src/v1.ts"
  },
  "scripts": {
    "typecheck": "tsc --noEmit",
    "test": "bun test"
  },
  "dependencies": {
    "@opencode-ai/plugin": "0.0.0-v1-202510310553",
    "@opencode/plugin": "0.0.0-beta-19296"
  },
  "devDependencies": {
    "@types/bun": "1.4.2",
    "typescript": "7.0.2"
  },
  "engines": {
    "node": ">=18",
    "opencode": ">=0.0.0-beta-18684"
  },
  "files": ["bin", "src", "commands", "README.md", "LICENSE"],
  "keywords": ["opencode", "opencode-plugin", "visual-inspector", "frontend", "cli", "installer"],
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/frontendxlab/opencode-annotate.git"
  },
  "homepage": "https://opencode-annotate.frontendx.dev",
  "bugs": "https://github.com/frontendxlab/opencode-annotate/issues",
  "license": "MIT"
}
